WITH cleaned AS (SELECT id, customer_id, store_id, order_date, channel, amount, discount, shipping_fee, DATEDIFF(CURRENT_DATE(), order_date) / 7 AS weeks_since_order_date, COALESCE(shipping_fee, 0) AS shipping_fee_filled, COALESCE(channel, 'N/A') AS resolved_channel FROM orders WHERE order_date > DATE '2023-04-08' AND customer_id IS NOT NULL) SELECT channel, store_id FROM cleaned EXCEPT SELECT channel, store_id FROM orders WHERE discount IS NOT NULL
